import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import vm from 'node:vm';
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_MODULE);
const dir='public-review-cloud-evidence',origin='https://shiftsometimber.co.uk',account='/accounts/9e5386dcf455be34c582d93f8bfc79e6',zone='/zones/66ec3268950adcfc837b7b8b2f8356ed',name='shift-public-review-fixes-20261029';
const cf='https://api.cloudflare.com/client/v4',gh='https://api.github.com/repos/shiftsometimber/shift-core';
const sha=x=>createHash('sha256').update(x).digest('hex'),save=(n,x)=>fs.writeFileSync(dir+'/'+n+'.json',JSON.stringify(x,null,2));
async function api(path,options={}){const r=await fetch(cf+path,{...options,headers:{Authorization:'Bearer '+process.env.CLOUDFLARE_API_TOKEN,...options.headers},signal:AbortSignal.timeout(30000),redirect:'error'});const b=await r.json();assert(r.ok&&b.success!==false,'Cloudflare operation failed '+r.status+' '+path);return b.result}
async function guard(){const r=await fetch(gh+'/actions/runs?status=in_progress&per_page=50',{headers:{Authorization:'Bearer '+process.env.GITHUB_TOKEN,'User-Agent':'SHIFT-public-review'}});assert(r.ok);for(const x of (await r.json()).workflow_runs.filter(x=>x.name==='Cloudflare Production Promote')){const j=await fetch(gh+'/actions/runs/'+x.id+'/jobs?per_page=100',{headers:{Authorization:'Bearer '+process.env.GITHUB_TOKEN,'User-Agent':'SHIFT-public-review'}});assert(j.ok);for(const job of (await j.json()).jobs.filter(x=>x.name==='promote'&&x.status==='in_progress'))assert(!job.steps.some(s=>s.number>=25&&['in_progress','completed'].includes(s.status)),'Active Core public baseline: no mutation allowed')}}
async function snap(){return {routes:await api(zone+'/workers/routes'),pages:(await api(account+'/pages/projects/projectshift')).canonical_deployment.id,core:(await api(account+'/workers/scripts/shift-core/deployments')).deployments[0],ticker:(await api(account+'/workers/scripts/shift-latest-news-ticker-20261024/deployments')).deployments[0]}}
const baseline=JSON.parse(fs.readFileSync(dir+'/baseline.json')),before=await snap();assert.equal(before.pages,baseline.pages.id);assert.deepEqual(before.core,baseline.workers['shift-core']);assert.deepEqual(before.ticker,baseline.workers['shift-latest-news-ticker-20261024']);
const paths=['/assets/v42.js','/assets/home-shell-v1.js'],assets={};
for(const path of paths){const r=await fetch(origin+path,{headers:{'Cache-Control':'no-cache'}});assert(r.ok);const b=await r.text(),file=path.split('/').at(-1);assert.equal(b,fs.readFileSync(dir+'/current-'+file,'utf8'));assets[path]={body:fs.readFileSync(dir+'/candidate-'+file,'utf8'),headers:Object.fromEntries([...r.headers].filter(([k])=>!['content-length','content-encoding','etag','last-modified','cf-ray','cf-cache-status','date','server','age','connection','transfer-encoding','set-cookie'].includes(k)))};new vm.Script(assets[path].body)}
const storyPath='/medicine-news/antidepressant-safety-information-mhra-october-2026';
async function dates(fetcher){const r=await fetcher('https://shiftsometimber.co.uk'+storyPath,{redirect:'error',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('Article unavailable');const html=await r.text();for(const m of html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/g)){let j;try{j=JSON.parse(m[1])}catch{continue}if(j['@type']==='Article'&&j.mainEntityOfPage==='https://shiftsometimber.co.uk'+storyPath&&Number.isFinite(Date.parse(j.datePublished))&&Number.isFinite(Date.parse(j.dateModified))&&Date.parse(j.datePublished)<=Date.parse(j.dateModified)&&Date.parse(j.dateModified)<=Date.now())return{published:j.datePublished,modified:j.dateModified}}throw Error('Authoritative article dates missing')}
function correct(body,d){if(body.ok!==true||!Array.isArray(body.items))return body;return {...body,items:body.items.map(row=>row.id===1263&&row.metadata?.canonical==='https://shiftsometimber.co.uk'+storyPath?{...row,published_at:d.published,metadata:{...row.metadata,datePublished:d.published,dateModified:d.modified}}:row)}}
const authoritative=await dates(fetch);assert.equal(authoritative.published,'2026-10-19T19:55:33.000Z');assert.equal(authoritative.modified,'2026-10-20T07:09:41.617Z');
const newsResponse=await fetch(origin+'/v1/radar/news');assert(newsResponse.ok);const oldNews=await newsResponse.json(),newNews=correct(oldNews,authoritative),idx=oldNews.items.findIndex(x=>x.id===1263);assert(idx>=0);
for(let i=0;i<oldNews.items.length;i++)if(i!==idx)assert.deepEqual(newNews.items[i],oldNews.items[i]);else {assert.equal(newNews.items[i].article_markdown,oldNews.items[i].article_markdown);assert.equal(newNews.items[i].headline,oldNews.items[i].headline)}
save('projection-tests',{pass:true,authoritative,unchangedOtherRows:oldNews.items.length-1,clinicalOrCommercialChanges:false});
const worker="const assets="+JSON.stringify(assets)+";const storyPath="+JSON.stringify(storyPath)+";"+dates.toString()+";"+correct.toString()+";export default {async fetch(request){const u=new URL(request.url);if(!['shiftsometimber.co.uk','www.shiftsometimber.co.uk'].includes(u.hostname))return new Response(null,{status:404});if(assets[u.pathname]){if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405});return new Response(request.method==='HEAD'?null:assets[u.pathname].body,{headers:assets[u.pathname].headers})}if(u.pathname!=='/v1/radar/news')return new Response(null,{status:404});if(request.method!=='GET')return new Response(null,{status:405});const upstream=await fetch('https://api.shiftsometimber.co.uk/v1/radar/news'+u.search,{redirect:'error'});if(!upstream.ok)return upstream;const raw=await upstream.text();try{const body=JSON.parse(raw),d=await dates(fetch),fixed=correct(body,d);const h=new Headers(upstream.headers);for(const k of ['content-length','content-encoding','etag','last-modified'])h.delete(k);h.set('cache-control','no-store');h.set('x-shift-public-review','20261029');return new Response(JSON.stringify(fixed),{status:upstream.status,headers:h})}catch{return new Response(raw,upstream)}}};";
fs.writeFileSync(dir+'/worker.mjs',worker);
async function browserCheck(staged,expectFixed=false){const browser=await chromium.launch({headless:true});const results=[];try{for(const width of [390,1440]){for(const path of ['/','/treatment-centre','/member/dashboard']){const context=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block'});try{await context.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());if(!['GET','HEAD'].includes(req.method()))return route.abort();if(/google-analytics|googletagmanager/.test(u.hostname))return route.abort();if(staged&&u.origin===origin&&assets[u.pathname])return route.fulfill({status:200,body:assets[u.pathname].body,headers:assets[u.pathname].headers});if(staged&&u.origin===origin&&u.pathname==='/v1/radar/news')return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(newNews)});return route.continue()});
const page=await context.newPage();await page.goto(origin+path,{waitUntil:'networkidle',timeout:60000});const necessary=page.getByRole('button',{name:'Necessary only',exact:true});if(await necessary.isVisible())await necessary.click();
const value=await page.evaluate(()=>({main:document.querySelector('main')?.innerHTML,header:document.querySelector('header.site-header')?.innerHTML,footer:document.querySelector('footer.site-footer')?.innerHTML,heading:[...document.querySelectorAll('#sst-footer-c .fc-main h2')].map(e=>getComputedStyle(e).color),footerCount:document.querySelectorAll('footer.site-footer').length,overflow:document.documentElement.scrollWidth>innerWidth}));
assert.equal(value.footerCount,1);assert.equal(value.overflow,false);
if(staged&&path!=='/')assert(value.heading.length&&value.heading.every(c=>c==='rgb(112, 119, 98)'));
if(path!=='/'){await page.getByRole('button',{name:'Menu',exact:true}).click();const labels=await page.locator('#site-drawer nav > a').allTextContents();assert.deepEqual(labels.slice(0,5),['Start Here','The Programme','SHIFT Health','Treatments','My Timber']);value.drawer=labels;if(staged||expectFixed)assert.deepEqual(labels.slice(5),[...labels.slice(5)].sort((a,b)=>a.trim().localeCompare(b.trim(),'en-GB',{sensitivity:'base'})));}
if((staged||expectFixed)&&path==='/treatment-centre')await page.locator('#shift-public-news .shift-news-copy').first().getByRole('link',{name:'MHRA strengthens antidepressant safety information · Updated 20 Oct 2026',exact:true}).waitFor({state:'visible',timeout:15000});results.push({width,path,...value});await page.screenshot({path:dir+'/'+(staged?'candidate':expectFixed?'production':'baseline')+'-'+width+'-'+(path==='/'?'home':path.slice(1).replaceAll('/','-'))+'.png',fullPage:true});
}finally{await context.close()}}}}finally{await browser.close()}return results}
const original=await browserCheck(false),candidate=await browserCheck(true);save('baseline-browser',{cases:original.map(({width,path,main,header,footer,heading})=>({width,path,mainSha256:sha(main||''),headerSha256:sha(header||''),footerSha256:sha(footer||''),heading}))});
for(let i=0;i<original.length;i++)if(original[i].path==='/')for(const k of ['main','header','footer','heading'])assert.deepEqual(candidate[i][k],original[i][k],'Homepage rendered '+k+' changed');
save('candidate-browser',{pass:true,cases:candidate.map(({width,path,heading,footerCount,overflow})=>({width,path,heading,footerCount,overflow})),homepagePreserved:true,source:process.env.GITHUB_SHA});
await guard();assert.deepEqual(await snap(),before,'Concurrent deployment: stop');
const patterns=['shiftsometimber.co.uk/assets/v42.js*','shiftsometimber.co.uk/assets/home-shell-v1.js*','shiftsometimber.co.uk/v1/radar/news*'];
assert(patterns.every(p=>!before.routes.some(r=>r.pattern===p)),'An exact route already has an owner');
const existing=await fetch('https://api.cloudflare.com/client/v4'+account+'/workers/scripts/'+name+'/deployments',{headers:{Authorization:'Bearer '+process.env.CLOUDFLARE_API_TOKEN}});assert.equal(existing.status,404,'New scoped owner name already exists: reconcile');
save('before',{...before,source:process.env.GITHUB_SHA,patterns,workerSha256:sha(worker)});
const form=new FormData();form.append('metadata',JSON.stringify({main_module:'worker.mjs',compatibility_date:'2026-08-09',bindings:[],tags:['matt-approved-public-review-20261029']}));form.append('worker.mjs',new File([worker],'worker.mjs',{type:'application/javascript+module'}),'worker.mjs');
const uploaded=await api(account+'/workers/scripts/'+name,{method:'PUT',body:form});save('upload',{at:new Date().toISOString(),id:uploaded.id,version:uploaded.deployment_id,source:process.env.GITHUB_SHA});
const owned=[];try {await guard();assert.deepEqual(await snap(),before,'Concurrent release before route activation');for(const pattern of patterns){const route=await api(zone+'/workers/routes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({pattern,script:name})});owned.push(route);save('owned-routes',owned)}
const after=await snap();assert.equal(after.pages,before.pages);assert.deepEqual(after.core,before.core);assert.deepEqual(after.ticker,before.ticker);
const publicNews=await (await fetch(origin+'/v1/radar/news',{headers:{'Cache-Control':'no-cache'}})).json();assert.equal(publicNews.items.find(x=>x.id===1263).metadata.datePublished,authoritative.published);
for(const path of paths){const r=await fetch(origin+path,{headers:{'Cache-Control':'no-cache'}});assert.equal(await r.text(),assets[path].body)}
const live=await browserCheck(false,true);for(const c of live.filter(x=>x.path!=='/'))assert(c.heading.length&&c.heading.every(x=>x==='rgb(112, 119, 98)'));for(let i=0;i<original.length;i++)if(original[i].path==='/')for(const k of ['main','header','footer','heading'])assert.deepEqual(live[i][k],original[i][k]);
save('production-verification',{pass:true,at:new Date().toISOString(),source:process.env.GITHUB_SHA,patterns,owned,coreUnchanged:true,pagesUnchanged:true,homepagePreserved:true,dates:authoritative,desktopMobileCases:live.length});console.log('VERIFIED_PRODUCTION '+JSON.stringify({source:process.env.GITHUB_SHA,patterns,dates:authoritative,cases:live.length}));
}catch(error){const current=await api(zone+'/workers/routes');for(const route of owned){const row=current.find(x=>x.id===route.id);assert(row?.script===name&&row.pattern===route.pattern,'Concurrent owner change: rollback refused');await api(zone+'/workers/routes/'+route.id,{method:'DELETE'})}save('rollback',{at:new Date().toISOString(),removedOwnedRoutes:owned,error:String(error),snapshot:await snap()});throw error}
